+#[derive(Debug, PartialEq, Eq)]
+struct FileRecord {
+    relative: std::path::PathBuf,
+    device: u64,
+    inode: u64,
+    uid: u32,
+    gid: u32,
+    mode: u32,
+    links: u64,
+    directory: bool,
